const canonicalIncomeSources = canonicalIncomeSourcesRaw.map((source) => {
  const netMonthlyCashflow = source.netMonthlyPassiveIncome;
  const includedInCoreRate = source.exclusionReason === null;
  const sourceWithoutAmbiguousField = { ...source };
  delete sourceWithoutAmbiguousField.netMonthlyPassiveIncome;
  return {
    ...sourceWithoutAmbiguousField,
    netMonthlyCashflow,
    eligibleMonthlyPassiveIncome: includedInCoreRate ? netMonthlyCashflow : 0,
    includedInCoreRate,
  };
});

